using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using TechnifyERP.Application.Badges;
namespace TechnifyERP.Areas.Faculty.Controllers;[Area("Faculty"),Authorize(Roles="Faculty")]public sealed class BadgesController(IBadgeService service):Controller{public async Task<IActionResult>Index(CancellationToken ct){ViewBag.Badges=(await service.GetAllAsync(ct)).Select(x=>new SelectListItem(x.Name,x.Id.ToString()));ViewBag.Students=(await service.GetAwardableStudentsAsync(Id,ct)).Select(x=>new SelectListItem($"{x.RegistrationNumber} — {x.FullName} ({x.CourseCode})",x.UserId));return View();}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Award(int badgeId,string studentId,CancellationToken ct){var r=await service.AwardAsync(Id,badgeId,studentId,ct);TempData[r==BadgeActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==BadgeActionResult.Success?"Badge award ho gaya.":r==BadgeActionResult.Duplicate?"Yeh badge pehle se award hai.":"Badge award nahi hua.";return RedirectToAction(nameof(Index));}private string Id=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;}
